/// <summary>
/// MPJ_28810_BuildDeliveryNote
/// </summary>
protected void preRunModifyContract()
{
    METDeliveryNoteContract contract = this.parmReportContract().parmRdpContract() as METDeliveryNoteContract;
    if(this.parmArgs().dataset() == tableNum(CustPackingSlipJour))
    {
        CustPackingSlipJour custPackingSlipJour = this.parmArgs().record() as CustPackingSlipJour;
        contract.parmPackingSlipRecId(custPackingSlipJour.RecId);
    }
}

/// <summary>
/// MPJ_28810
/// constructor
/// </summary>
/// <returns>constructor</returns>
public static METDeliveryNoteController construct()
{
    return new METDeliveryNoteController();
}

/// <summary>
/// MPJ_28810
/// Main method to run report
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    METDeliveryNoteController controller  = METDeliveryNoteController::construct();
    controller.parmReportName(ssrsReportStr(METDeliveryNote, Report));
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:METDeliveryNote");
    controller.startOperation();
}
